package com.companion.agent.tool;
import com.companion.ai.MemoryEngine;import com.companion.dto.response.*;import com.companion.service.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import java.util.List;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class AgentReadOnlyToolsTest {ObjectMapper json=new ObjectMapper();
 @Test void characterToolUsesOwnedServiceAndValidatesArguments(){CharacterService s=mock(CharacterService.class);CharacterResponse c=new CharacterResponse();c.setId(5L);c.setName("Nova");when(s.get(9L,5L)).thenReturn(c);String out=new GetCharacterContextTool(s,json).execute(9L,json.createObjectNode().put("characterId",5));assertThat(out).contains("Nova");verify(s).get(9L,5L);assertThatThrownBy(()->new GetCharacterContextTool(s,json).execute(9L,json.createObjectNode().put("characterId",5).put("userId",1))).isInstanceOf(Exception.class);}
 @Test void memoryToolValidatesOwnershipBeforeScopedRead(){CharacterService c=mock(CharacterService.class);MemoryEngine m=mock(MemoryEngine.class);when(m.getMemoryContext(9L,5L,"preferences")).thenReturn("likes tea");String out=new SearchCharacterMemoryTool(c,m).execute(9L,json.createObjectNode().put("characterId",5).put("query","preferences"));assertThat(out).isEqualTo("likes tea");var order=inOrder(c,m);order.verify(c).get(9L,5L);order.verify(m).getMemoryContext(9L,5L,"preferences");verifyNoMoreInteractions(m);}
 @Test void worldToolUsesOwnedWorldService(){CharacterWorldService s=mock(CharacterWorldService.class);WorldResponse w=new WorldResponse();w.setId(7L);w.setName("Library");when(s.get(9L,7L)).thenReturn(w);assertThat(new GetWorldContextTool(s,json).execute(9L,json.createObjectNode().put("worldId",7))).contains("Library");verify(s).get(9L,7L);}
 @Test void crossUserCharacterAndWorldDenialsPropagateWithoutMemoryRead(){CharacterService characters=mock(CharacterService.class);CharacterWorldService worlds=mock(CharacterWorldService.class);MemoryEngine memory=mock(MemoryEngine.class);var denied=new com.companion.common.exception.BusinessException(com.companion.common.result.ResultCode.NOT_FOUND);when(characters.get(9L,5L)).thenThrow(denied);when(worlds.get(9L,7L)).thenThrow(denied);assertThatThrownBy(()->new SearchCharacterMemoryTool(characters,memory).execute(9L,json.createObjectNode().put("characterId",5).put("query","preferences"))).isSameAs(denied);assertThatThrownBy(()->new GetWorldContextTool(worlds,json).execute(9L,json.createObjectNode().put("worldId",7))).isSameAs(denied);verifyNoInteractions(memory);}
}
